package binding

import (
	"fmt"
	"strconv"
)

// FormatFloat creates a String binding that formats a Float binding using the specified format string.
// The format string follows fmt.Sprintf conventions (e.g., "%.2f" for 2 decimal places).
// Changes to the Float binding will automatically update the formatted String binding.
//
// Since: 2.5
func FormatFloat(v Float, format string) String {
	if v == nil {
		return NewString()
	}

	str := NewString()

	// Set initial value
	if val, err := v.Get(); err == nil {
		str.Set(fmt.Sprintf(format, val))
	}

	// Listen for changes
	v.AddListener(NewDataListener(func() {
		val, err := v.Get()
		if err != nil {
			return
		}
		str.Set(fmt.Sprintf(format, val))
	}))

	return str
}

// FormatInt creates a String binding that formats an Int binding using the specified format string.
// The format string follows fmt.Sprintf conventions (e.g., "%d" for decimal, "%x" for hex).
// Changes to the Int binding will automatically update the formatted String binding.
//
// Since: 2.5
