package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strings"

	"fyne.io/fyne/v2"
)

// jsonTheme is an internal implementation of fyne.Theme loaded from JSON data
type jsonTheme struct {
	colors map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color
	sizes  map[fyne.ThemeSizeName]float32
}

// Color returns the color for the given color name and variant
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	if t.colors == nil {
		return DefaultTheme().Color(name, variant)
	}

	if variants, ok := t.colors[name]; ok {
		if c, ok := variants[variant]; ok {
			return c
		}
	}

	return DefaultTheme().Color(name, variant)
}

// Font returns the font resource for the given text style
// JSON themes fall back to the default theme for fonts
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	return DefaultTheme().Font(style)
}

// Icon returns the icon resource for the given icon name
// JSON themes fall back to the default theme for icons
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	return DefaultTheme().Icon(name)
}

// Size returns the size for the given size name
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.sizes == nil {
		return DefaultTheme().Size(name)
	}

	if size, ok := t.sizes[name]; ok {
		return size
	}

	return DefaultTheme().Size(name)
}

// FromJSON creates a Theme from JSON string data.
// The JSON should have the following structure:
//
//	{
//	  "Colors": {"colorName": "#hexvalue", ...},           // variant-agnostic colors
//	  "Colors-dark": {"colorName": "#hexvalue", ...},      // dark variant colors
//	  "Colors-light": {"colorName": "#hexvalue", ...},     // light variant colors
//	  "Sizes": {"sizeName": floatValue, ...}
//	}
//
// Hex values support 3, 4, 6, and 8 digit formats (#RGB, #RGBA, #RRGGBB, #RRGGBBAA).
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader creates a Theme from JSON data read from an io.Reader.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw struct {
		Colors      map[string]string  `json:"Colors"`
		ColorsDark  map[string]string  `json:"Colors-dark"`
		ColorsLight map[string]string  `json:"Colors-light"`
		Sizes       map[string]float32 `json:"Sizes"`
	}

	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&raw); err != nil {
		return nil, err
	}

	theme := &jsonTheme{
		colors: make(map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color),
		sizes:  make(map[fyne.ThemeSizeName]float32),
	}

	// Process variant-agnostic colors
	for name, hexStr := range raw.Colors {
		col, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("invalid color %s: %w", name, err)
		}
		colorName := fyne.ThemeColorName(name)
		theme.colors[colorName] = map[fyne.ThemeVariant]color.Color{
			fyne.VariantLight: col,
			fyne.VariantDark:  col,
		}
	}

	// Process dark variant colors
	for name, hexStr := range raw.ColorsDark {
		col, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("invalid dark color %s: %w", name, err)
		}
		colorName := fyne.ThemeColorName(name)
		if theme.colors[colorName] == nil {
			theme.colors[colorName] = make(map[fyne.ThemeVariant]color.Color)
		}
		theme.colors[colorName][fyne.VariantDark] = col
	}

	// Process light variant colors
	for name, hexStr := range raw.ColorsLight {
		col, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("invalid light color %s: %w", name, err)
		}
		colorName := fyne.ThemeColorName(name)
		if theme.colors[colorName] == nil {
			theme.colors[colorName] = make(map[fyne.ThemeVariant]color.Color)
		}
		theme.colors[colorName][fyne.VariantLight] = col
	}

	// Process sizes
	for name, value := range raw.Sizes {
		theme.sizes[fyne.ThemeSizeName(name)] = value
	}

	return theme, nil
}

// parseHexColor parses a hex color string in formats: #RGB, #RGBA, #RRGGBB, #RRGGBBAA
func parseHexColor(hex string) (color.Color, error) {
	if !strings.HasPrefix(hex, "#") {
		return nil, fmt.Errorf("hex color must start with #")
	}

	hex = hex[1:] // Remove '#'

	var r, g, b, a uint8
	a = 255 // Default alpha

	switch len(hex) {
	case 3: // #RGB
		rVal, err := parseHexDigit(hex[0])
		if err != nil {
			return nil, err
		}
		gVal, err := parseHexDigit(hex[1])
		if err != nil {
			return nil, err
		}
		bVal, err := parseHexDigit(hex[2])
		if err != nil {
			return nil, err
		}
		r = rVal*16 + rVal
		g = gVal*16 + gVal
		b = bVal*16 + bVal

	case 4: // #RGBA
		rVal, err := parseHexDigit(hex[0])
		if err != nil {
			return nil, err
		}
		gVal, err := parseHexDigit(hex[1])
		if err != nil {
			return nil, err
		}
		bVal, err := parseHexDigit(hex[2])
		if err != nil {
			return nil, err
		}
		aVal, err := parseHexDigit(hex[3])
		if err != nil {
			return nil, err
		}
		r = rVal*16 + rVal
		g = gVal*16 + gVal
		b = bVal*16 + bVal
		a = aVal*16 + aVal

	case 6: // #RRGGBB
		var err error
		r, err = parseHexByte(hex[0:2])
		if err != nil {
			return nil, err
		}
		g, err = parseHexByte(hex[2:4])
		if err != nil {
			return nil, err
		}
		b, err = parseHexByte(hex[4:6])
		if err != nil {
			return nil, err
		}

	case 8: // #RRGGBBAA
		var err error
		r, err = parseHexByte(hex[0:2])
		if err != nil {
			return nil, err
		}
		g, err = parseHexByte(hex[2:4])
		if err != nil {
			return nil, err
		}
		b, err = parseHexByte(hex[4:6])
		if err != nil {
			return nil, err
		}
		a, err = parseHexByte(hex[6:8])
		if err != nil {
			return nil, err
		}

	default:
		return nil, fmt.Errorf("invalid hex color length: %d", len(hex))
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigit parses a single hex digit (0-9, a-f, A-F)
func parseHexDigit(c byte) (uint8, error) {
	switch {
	case '0' <= c && c <= '9':
		return c - '0', nil
	case 'a' <= c && c <= 'f':
		return c - 'a' + 10, nil
	case 'A' <= c && c <= 'F':
		return c - 'A' + 10, nil
	default:
		return 0, fmt.Errorf("invalid hex digit: %c", c)
	}
}

// parseHexByte converts a 2-character hex string to a byte
func parseHexByte(hex string) (uint8, error) {
	if len(hex) != 2 {
		return 0, fmt.Errorf("hex byte must be 2 characters")
	}

	high, err := parseHexDigit(hex[0])
	if err != nil {
		return 0, err
	}
	low, err := parseHexDigit(hex[1])
	if err != nil {
		return 0, err
	}

	return high*16 + low, nil
}

