		colors: make(map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color),
		sizes:  make(map[fyne.ThemeSizeName]float32),
	}

	// Process variant-agnostic colors
	for name, hexStr := range raw.Colors {
		col, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("invalid color %s: %w", name, err)
		}
		colorName := fyne.ThemeColorName(name)
		theme.colors[colorName] = map[fyne.ThemeVariant]color.Color{
			fyne.VariantLight: col,
			fyne.VariantDark:  col,
		}
	}

	// Process dark variant colors
	for name, hexStr := range raw.ColorsDark {
		col, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("invalid dark color %s: %w", name, err)
		}
		colorName := fyne.ThemeColorName(name)
		if theme.colors[colorName] == nil {
			theme.colors[colorName] = make(map[fyne.ThemeVariant]color.Color)
		}
		theme.colors[colorName][fyne.VariantDark] = col
	}

	// Process light variant colors
	for name, hexStr := range raw.ColorsLight {
		col, err := parseHexColor(hexStr)
		if err != nil {
			return nil, fmt.Errorf("invalid light color %s: %w", name, err)
		}
		colorName := fyne.ThemeColorName(name)
		if theme.colors[colorName] == nil {
			theme.colors[colorName] = make(map[fyne.ThemeVariant]color.Color)
		}
		theme.colors[colorName][fyne.VariantLight] = col
	}

	// Process sizes
	for name, value := range raw.Sizes {
		theme.sizes[fyne.ThemeSizeName(name)] = value
	}

	return theme, nil
}

// parseHexColor parses a hex color string in formats: #RGB, #RGBA, #RRGGBB, #RRGGBBAA
func parseHexColor(hex string) (color.Color, error) {
	if !strings.HasPrefix(hex, "#") {
		return nil, fmt.Errorf("hex color must start with #")
	}

	hex = hex[1:] // Remove '#'

	var r, g, b, a uint8
	a = 255 // Default alpha

	switch len(hex) {
	case 3: // #RGB
		rVal, err := parseHexDigit(hex[0])
		if err != nil {
			return nil, err
		}
		gVal, err := parseHexDigit(hex[1])
		if err != nil {
			return nil, err
		}
		bVal, err := parseHexDigit(hex[2])
		if err != nil {
			return nil, err
		}
		r = rVal*16 + rVal
		g = gVal*16 + gVal
		b = bVal*16 + bVal

	case 4: // #RGBA
		rVal, err := parseHexDigit(hex[0])
		if err != nil {
			return nil, err
		}
		gVal, err := parseHexDigit(hex[1])
		if err != nil {
			return nil, err
		}
		bVal, err := parseHexDigit(hex[2])
		if err != nil {
			return nil, err
		}
		aVal, err := parseHexDigit(hex[3])
		if err != nil {
			return nil, err
		}
		r = rVal*16 + rVal
		g = gVal*16 + gVal
		b = bVal*16 + bVal
		a = aVal*16 + aVal

	case 6: // #RRGGBB
		var err error
		r, err = parseHexByte(hex[0:2])
		if err != nil {
			return nil, err
		}
		g, err = parseHexByte(hex[2:4])
		if err != nil {
			return nil, err
		}
		b, err = parseHexByte(hex[4:6])
		if err != nil {
			return nil, err
		}

	case 8: // #RRGGBBAA
		var err error
		r, err = parseHexByte(hex[0:2])
		if err != nil {
			return nil, err
		}
		g, err = parseHexByte(hex[2:4])
		if err != nil {
			return nil, err
		}
		b, err = parseHexByte(hex[4:6])
		if err != nil {
			return nil, err
		}
		a, err = parseHexByte(hex[6:8])
		if err != nil {
			return nil, err
		}

	default:
		return nil, fmt.Errorf("invalid hex color length: %d", len(hex))
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigit parses a single hex digit (0-9, a-f, A-F)
func parseHexDigit(c byte) (uint8, error) {
	switch {
	case '0' <= c && c <= '9':
		return c - '0', nil
	case 'a' <= c && c <= 'f':
		return c - 'a' + 10, nil
	case 'A' <= c && c <= 'F':
		return c - 'A' + 10, nil
	default:
		return 0, fmt.Errorf("invalid hex digit: %c", c)
	}
}

// parseHexByte converts a 2-character hex string to a byte
func parseHexByte(hex string) (uint8, error) {
	if len(hex) != 2 {
		return 0, fmt.Errorf("hex byte must be 2 characters")
	}

	high, err := parseHexDigit(hex[0])
	if err != nil {
		return 0, err
	}
	low, err := parseHexDigit(hex[1])
	if err != nil {
		return 0, err
	}

	return high*16 + low, nil
}

package binding

import (
	"fmt"
	"sync"
)

// NewSprintf creates a String binding that formats multiple DataItems using fmt.Sprintf.
// The format string follows fmt.Sprintf conventions. The binding updates automatically
// when any of the source DataItems change.
//
// Example:
//
//	name := binding.NewString()
//	age := binding.NewInt()
//	result := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		// No bindings, just return static string
		s := NewString()
		s.Set(format)
		return s
	}

	result := &sprintfBinding{
		format:  format,
		sources: b,
		val:     "",
	}

	// Initialize with current values
	result.update()

	// Listen to all source bindings
	listener := NewDataListener(func() {
		result.update()
	})

	for _, item := range b {
		if item != nil {
			item.AddListener(listener)
		}
	}

	return result
}

// sprintfBinding combines multiple DataItems using fmt.Sprintf
type sprintfBinding struct {
	base

	format  string
	sources []DataItem
	val     string
	lock    sync.RWMutex
}

// Get returns the formatted string value
func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.val, nil
}

// Set is not supported for sprintf bindings (read-only)
func (s *sprintfBinding) Set(string) error {
	return fmt.Errorf("cannot set value on sprintf binding")
}

// update recalculates the formatted string from source bindings
func (s *sprintfBinding) update() {
	values := make([]interface{}, len(s.sources))

	for i, item := range s.sources {
		if item == nil {
			values[i] = nil
			continue
		}

		// Extract the actual value from the DataItem
		switch v := item.(type) {
		case String:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = ""
			}
		case Int:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0
			}
		case Float:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0.0
			}
		case Bool:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = false
			}
		case Untyped:
			if val, err := v.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = nil
			}
		default:
			// For any other type, try to get as Untyped
			if untyped, ok := item.(Untyped); ok {
				if val, err := untyped.Get(); err == nil {
					values[i] = val
				} else {
					values[i] = nil
				}
			} else {
				values[i] = nil
			}
		}
	}

	newVal := fmt.Sprintf(s.format, values...)

	s.lock.Lock()
	changed := s.val != newVal
	s.val = newVal
	s.lock.Unlock()

	if changed {
		s.trigger()
	}
}

// StringToStringWithFormat creates a String binding that formats another String binding.
// The format string should contain a single %s placeholder for the source string value.
// Changes to the source String binding automatically update the formatted result.
//
// Example:
//
//	username := binding.NewString()
//	formatted := binding.StringToStringWithFormat(username, "User: %s")
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if str == nil {
		return NewString()
	}

	result := &stringFormatBinding{
		format: format,
		source: str,
		val:    "",
	}

	// Initialize with current value
	result.update()

	// Listen for changes
	str.AddListener(NewDataListener(func() {
		result.update()
	}))

	return result
}

// stringFormatBinding formats a String binding
type stringFormatBinding struct {
	base

	format string
	source String
	val    string
	lock   sync.RWMutex
}

// Get returns the formatted string value
func (s *stringFormatBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.val, nil
}

// Set is not supported for format bindings (read-only)
func (s *stringFormatBinding) Set(string) error {
	return fmt.Errorf("cannot set value on format binding")
}

// update recalculates the formatted string
func (s *stringFormatBinding) update() {
	val, err := s.source.Get()
	if err != nil {
		val = ""
	}

	newVal := fmt.Sprintf(s.format, val)

	s.lock.Lock()
	changed := s.val != newVal
	s.val = newVal
	s.lock.Unlock()

	if changed {
		s.trigger()
	}
}

