func (s *sprintfBinding) Set(str string) error {
	if len(s.sources) == 0 {
		return fmt.Errorf("no source bindings to set")
	}

	// Create pointers to hold parsed values
	args := make([]interface{}, len(s.sources))

	for i, item := range s.sources {
		if item == nil {
			return fmt.Errorf("source binding %d is nil", i)
		}

		// Create appropriate type for Sscanf based on binding type
		switch item.(type) {
		case String:
			var strVal string
			args[i] = &strVal
		case Int:
			var intVal int
			args[i] = &intVal
		case Float:
			var floatVal float64
			args[i] = &floatVal
		case Bool:
			var boolVal bool
			args[i] = &boolVal
		case URI:
			var uriVal string
			args[i] = &uriVal
		case Bytes:
			return fmt.Errorf("cannot set Bytes binding through sprintf")
		default:
			// For Untyped or unknown types, use interface{}
			var val interface{}
			args[i] = &val
		}
	}

	// Parse the string using fmt.Sscanf
	n, err := fmt.Sscanf(str, s.format, args...)
	if err != nil {
		return fmt.Errorf("failed to parse string: %w", err)
	}
	if n != len(s.sources) {
		return fmt.Errorf("expected %d values, parsed %d", len(s.sources), n)
	}

	// Set each source binding with the parsed value
	for i, item := range s.sources {
		switch v := item.(type) {
		case String:
			strVal := *(args[i].(*string))
			if err := v.Set(strVal); err != nil {
				return fmt.Errorf("failed to set string binding %d: %w", i, err)
			}
		case Int:
			intVal := *(args[i].(*int))
