			floatVal := *(args[i].(*float64))
			if err := v.Set(floatVal); err != nil {
				return fmt.Errorf("failed to set float binding %d: %w", i, err)
			}
		case Bool:
			boolVal := *(args[i].(*bool))
			if err := v.Set(boolVal); err != nil {
